Ts=(T-4)/2
def tens(di,dj):
    return np.column_stack([L**i*Ts**j for i in range(di+1) for j in range(dj+1)])
def test(y,di,dj,inv):
    A=tens(di,dj)
    c,*_=np.linalg.lstsq(A,y,rcond=None)
    p=inv(A@c)
